            j = k; continue;
          }
          out += nx; j += 2; continue;
        }
        if (ch === '(') depth++;
        if (ch === ')') { depth--; if (depth === 0) { j++; break; } }
        out += ch; j++;
      }
      toks.push({ t: 'str', v: out });
      i = j; continue;
    }
    if (c === '<' && src[i + 1] !== '<') {
      const j = src.indexOf('>', i);
      toks.push({ t: 'hex', v: src.slice(i + 1, j) });
      i = j + 1; continue;
    }
    if (c === '[') { toks.push({ t: 'arr_start' }); i++; continue; }
    if (c === ']') { toks.push({ t: 'arr_end' }); i++; continue; }
    if (c === '<' && src[i + 1] === '<') { toks.push({ t: 'dict_start' }); i += 2; continue; }
    if (c === '>' && src[i + 1] === '>') { toks.push({ t: 'dict_end' }); i += 2; continue; }
